93	func (s *service) listModelsForSubprocessHarness(filter ModelFilter) []ModelInfo {
94		name := harnesses.ResolveHarnessAlias(filter.Harness)
95		cfg, ok := s.registry.Get(name)
96		if !ok || harnessRunsInProcessOrHTTP(cfg) {
97			return nil
98		}
99		if filter.Provider != "" && filter.Provider != name {
100			return nil
101		}
102		cat, _ := modelcatalog.Default()
103		return s.subscriptionHarnessTierModels(name, cfg, cat)
104	}
