23	// fakeModelsServer returns an httptest.Server that serves the given model IDs from /v1/models.
24	func fakeModelsServer(models []string) *httptest.Server {
25		return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
26			if strings.HasSuffix(r.URL.Path, "/models") {
27				w.Header().Set("Content-Type", "application/json")
28				data := make([]map[string]any, len(models))
29				for i, m := range models {
30					data[i] = map[string]any{"id": m}
31				}
32				json.NewEncoder(w).Encode(map[string]any{"data": data})
33				return
34			}
35			http.NotFound(w, r)
36		}))
37	}
38	
39	func fakeFailingModelsServer(status int) *httptest.Server {
40		return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
41			if strings.HasSuffix(r.URL.Path, "/models") {
42				http.Error(w, "model list unavailable", status)
43				return
44			}
45			http.NotFound(w, r)
46		}))
47	}
